static void fibonacci(int n) {
  int a = 0, b = 1;
  for (int i = 0; i < n; i++) {
    System.out.print(a + " ");
    int next = a + b;
    a = b;
    b = next;
  }
}

static Map<Character, Integer> frequency(String s) {
  Map<Character, Integer> map = new HashMap<>();
  for (char c : s.toCharArray()) {
    map.put(c, map.getOrDefault(c, 0) + 1);
  }
  return map;
}

