const unique = arr => [...new Set(arr)];

function uniqueLoop(arr) {
  const result = [];
  for (const x of arr) {
    if (!result.includes(x)) result.push(x);
  }
  return result;
}

console.log(unique([1, 2, 2, 3, 1])); // [1, 2, 3]

function wordCount(sentence) {
  const counts = {};
  for (const word of sentence.toLowerCase().split(' ')) {
    counts[word] = (counts[word] || 0) + 1;
  }
  return counts;
}

console.log(wordCount('to be or not to be'));
// { to: 2, be: 2, or: 1, not: 1 }
